    """Fill the masked cyclic pattern; cells below the diagonal use next phase."""
    h, w = len(grid), len(grid[0])
    # The first row exposes the repeating sequence except where masked.
    known = [(c, v) for c, v in enumerate(grid[0]) if v != 0]
    if not known:
        raise ValueError("cannot infer sequence from an all-zero first row")
    period = None
    for p in range(1, w + 1):
        if all(v == next((vv for cc, vv in known if cc % p == c % p), v)
               for c, v in known):
            # Verify all observations sharing a residue agree.
            by_residue = {}
            for c, v in known:
                if c % p in by_residue and by_residue[c % p] != v:
                    break
                by_residue[c % p] = v
            else:
                period = p
                break
    if period is None:
        period = w
    values = [None] * period
    for c, v in known:
        values[c % period] = v
    # If some phases are absent in the first row, recover them from any
    # unshifted cell in the grid (c >= r); otherwise fail explicitly.
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v and c >= r and values[c % period] is None:
                values[c % period] = v
    if any(v is None for v in values):
        raise ValueError("not enough visible cells to infer every cycle phase")
    return [[values[(c + (1 if c < r else 0)) % period]
             for c in range(w)] for r in range(h)]

